checked AS (
SELECT s.*,
CASE WHEN stream='awards' THEN EXISTS(SELECT 1 FROM core.awards a WHERE a.ca_notice_id=s.id)
 ELSE EXISTS(SELECT 1 FROM core.notices n WHERE n.c_notice_id=s.id) END AS in_core,
EXISTS(SELECT 1 FROM raw.raw_documents r WHERE r.source='elicitatie'
 AND r.external_id=(CASE WHEN stream='awards' THEN 'award:' ELSE 'tender:' END)||s.id
 AND r.endpoint_version=(CASE WHEN stream='awards' THEN 'award-list:v1' ELSE 'tender-list:v1' END)) AS in_raw,
EXISTS(SELECT 1 FROM core.contracts c WHERE c.ca_notice_id=s.id) AS has_contracts
FROM samples s
)
SELECT row_to_json(x) FROM (
SELECT year,stream,count(*) sampled,count(*) FILTER(WHERE in_core) in_core,count(*) FILTER(WHERE in_raw) in_raw,
count(*) FILTER(WHERE NOT in_core AND NOT in_raw) missing,
array_agg(id ORDER BY id) FILTER(WHERE NOT in_core AND NOT in_raw) missing_ids,
count(*) FILTER(WHERE stream='awards' AND has_contracts) awards_with_contracts
FROM checked GROUP BY 1,2 ORDER BY 1,2
)x;
COMMIT;
